// See README.md for license details.
// =============================================================================
//  NCoreBackendGemmSoftmaxSpec.scala — GEMM + Softmax quantization pipeline test
//
//  Models the post-accumulation activation of a transformer attention block:
//
//    softmax( QK^T / sqrt(d_k) )
//
//  Full pipeline (attention score → INT8 softmax weights):
//
//  Preamble — load LUT banks via vsetlut (once per kernel)
//    exp   table → bank A   (used in Phase 4)
//    recip table → bank B   (used in Phase 6)
//
//  Phase 0  — Seed FP32 accumulator (simulates GEMM / QK^T output in VR[0])
//    vbcastImm(acc) → VX[8];  vcvt_s8_f32 → VR[0]
//
//  Phase 1  — Attention score scaling  (multiply by scale ≈ 1/√d_k)
//    vbcastImm(scale) → VX[8];  vcvt_s8_f32 → VR[2];  vfmul → VR[1]
//
//  Phase 2  — FP32 → SQ1.6 INT8 quantize
//    vcvt(F32→S8, sat)  VR[1] → VX[0]
//
//  Phase 3  — Numerical stability: x - max(x)
//    vrmax VX[0] → VR[3];  extWrite max → VX[5];  vsub → VX[1]
//
//  Phase 4  — Element-wise exp LUT via vlut bank A  (SQ1.6 → UQ0.8)
//    vlut(bank=A)  VX[1] → VX[2]
//
//  Phase 5  — Horizontal sum of exp
//    vsum VX[2] → VR[4];  extWrite clamped sum → VX[6]
//
//  Phase 6  — Reciprocal of sum via vlut bank B  (SQ1.6 → SQ1.6)
//    vlut(bank=B)  VX[6] → VX[7]
//
//  Phase 7  — Promote INT8 → FP32 then multiply
//    vcvt_s8_f32 VX[2]→VR[5];  vcvt_s8_f32 VX[7]→VR[6];  vfmul→VR[7]
//
//  Phase 8  — INT32 right-shift to recover quantized probability
//    vcvt_f32_s32 VR[7]→VR[0];  vsra(>>7) VR[0]→VR[3]
//
//  Phase 9  — Narrow INT32 → INT8 saturated
//    vcvt_s32_s8 sat  VR[3] → VR[2]
//
//  LUT loading protocol (vsetlut via backend):
//    vsetlut is an I-type instruction that reads from in_a_vr (vr_a_addr) and
//    writes K×4 table bytes into the selected bank at the given segment offset.
//    Since the backend has no direct VR immediate-write, the test harness
//    uses extWrite to populate four VX rows with packed byte data, then issues
//    vcvt_s8_f32 (INT8→FP32, widening) to load those rows into VR.
//    NOTE: vcvt_s8_f32 promotes INT8 to FP32 (not a raw byte copy), so it
//    cannot directly pack table bytes into VR.  Instead, we use a simpler
//    direct approach: poke the VALU ctrl + in_a_vr directly is not available
//    through the backend; we load via extWrite + 4× vcvt_s8_s32 (sign-extend
//    single byte to VR lane) for each set of K entries.
//
//    Simplest practical approach for the backend test: write the K×4 raw bytes
//    of each segment directly into four consecutive VX registers (each holding
//    K bytes for one sub-row of the segment), then use the vsetlut instruction.
//    The vsetlut reads in_a_vr[k][8*(b+1)-1:8*b] = segment byte k*4+b.
//    To get these bytes into VR, we use extWrite to write 4 groups of K bytes
//    into VX[20..23] (scratch), then issue a vcvt_s8_s32 chain to assemble
//    a VR register with the correct byte layout.
//
//    For test simplicity we use an alternative: populate VR directly by
//    issuing vbcastImm for each byte lane and packing into a VR via shifted
//    OR.  Given K=8 (32 bytes per segment) and the K×4 packing, this requires
//    a 4-pass approach.  The loadLutBank helper below encapsulates this.
// =============================================================================

package backend

import chisel3._
import chisel3.simulator.EphemeralSimulator._
import org.scalatest.flatspec.AnyFlatSpec
import isa._
import alu.vec.{FpRef, Qfmt}

class NCoreBackendGemmSoftmaxSpec extends AnyFlatSpec {
  import NpuAssembler._

  val K = 8
  val N = 8

  // ---------------------------------------------------------------------------
  // Simulation helpers
  // ---------------------------------------------------------------------------

  def withBackend(body: NCoreBackend => Unit): Unit =
    simulate(new NCoreBackend(K, N, 32)) { dut =>
      dut.io.vx_a_addr.poke(0.U);   dut.io.vx_b_addr.poke(0.U);   dut.io.vx_out_addr.poke(0.U)
      dut.io.ve_a_addr.poke(0.U);   dut.io.ve_b_addr.poke(0.U);   dut.io.ve_out_addr.poke(0.U)
      dut.io.vr_a_addr.poke(0.U);   dut.io.vr_b_addr.poke(0.U);   dut.io.vr_c_addr.poke(0.U)
      dut.io.vr_out_addr.poke(0.U)
      dut.io.mma_a_addr.poke(0.U);  dut.io.mma_b_addr.poke(0.U);  dut.io.mma_out_addr.poke(0.U)
      dut.io.ext_wr_en.poke(false.B); dut.io.ext_wr_addr.poke(0.U)
      for (i <- 0 until K) dut.io.ext_wr_data(i).poke(0.U)
      dut.io.ext_rd_addr.poke(0.U)
      dut.io.vr_rd_addr.poke(0.U)
      dut.io.instr.poke((nop.toLong & 0xFFFFFFFFL).U)
      body(dut)
    }

  /** Write K bytes to VX[addr] via external write port. */
  def extWrite(dut: NCoreBackend, addr: Int, data: Array[Int]): Unit = {
    dut.io.ext_wr_en.poke(true.B)
    dut.io.ext_wr_addr.poke(addr.U)
    data.zipWithIndex.foreach { case (v, i) => dut.io.ext_wr_data(i).poke((v & 0xFF).U) }
    dut.io.instr.poke((nop.toLong & 0xFFFFFFFFL).U)
    dut.clock.step()
    dut.io.ext_wr_en.poke(false.B)
  }

  /**
   * Issue one instruction, hold for `cycles` clocks, then one NOP cycle.
   * Default cycles=2: 1 execute + 1 write-back (VALU 1-cycle output register).
   */
  def issue(dut: NCoreBackend, instr: Int, cycles: Int = 2): Unit = {
    dut.io.instr.poke((instr.toLong & 0xFFFFFFFFL).U)
    for (_ <- 0 until cycles) dut.clock.step()
    dut.io.instr.poke((nop.toLong & 0xFFFFFFFFL).U)
    dut.clock.step()
  }

  /**
   * Peek VR[addr] lane 0 as a signed INT32.
   * step(0) forces combinational re-evaluation in EphemeralSimulator.
   */
  def peekVR0(dut: NCoreBackend, addr: Int): Int = {
    dut.io.vr_a_addr.poke(addr.U)
    dut.clock.step(0)
    dut.io.vr_rd_data(0).peek().litValue.toInt
  }

  // ---------------------------------------------------------------------------
  // loadLutBank: load a 256-byte LUT table into bank A (0) or B (1) via vsetlut.
  //
  // For each segment s (0..segs-1):
  //   1. Write K×4 table bytes into four consecutive VX scratch registers
  //      VX[24..27], each holding one sub-row of K bytes:
  //        VX[24] = bytes [s×K×4+0, s×K×4+4, ..., s×K×4+4×(K-1)]   (b=0 of each lane)
  //        VX[25] = bytes [s×K×4+1, ...]                              (b=1)
  //        VX[26] = bytes [s×K×4+2, ...]                              (b=2)
  //        VX[27] = bytes [s×K×4+3, ...]                              (b=3)
  //   2. Load VX[24..27] into a VR staging register via 4 word-OR passes
  //      using VALU arith shifted into VR.
  //
  //   Simpler path used here: populate VR via the multi-width RF write directly.
  //   We use vcvt_s8_s32 (sign-extend VX lane k low byte → VR lane k bits[7:0])
  //   along with shift+OR logic to pack 4 bytes per lane.  However, the backend
  //   doesn't expose a raw byte-pack path.
  //
  //   Practical workaround: since we need 4 bytes per VR lane (UInt(32.W)), and
  //   each vbcastImm / extWrite can only set one value, we use the following
  //   4-pass approach per segment:
  //     Pass 0: extWrite VX[scratch_vx] with byte0 of each lane
  //             vcvt_s8_s32(VX[scratch_vx] → VR[staging])
  //             → VR[staging][k] = sign_ext(byte0[k])  (low 8 bits correct)
  //     Pass 1: extWrite VX[scratch_vx] with byte1
  //             manually shift+OR in Scala (we can't do << in VR without VALU)
  //
  //   This is complex.  Cleanest alternative for the test: since vsetlut reads
  //   in_a_vr, which is driven by vr_r_data(0) = rf[vr_a_addr], and the RF VR
  //   read packs 4 consecutive VX rows into one VR lane, we can write the 4
  //   VX sub-rows and then use vr_a_addr to point at that VR.
  //
  //   Segment s maps to VR[s] (since 256/(K×4)=8 and we have 8 VR regs at K=8).
  //   For K=8, VR[s] = VX[4s..4s+3].  We write those 4 VX rows with extWrite,
  //   then issue vsetlut with vr_a_addr=s.  This is the cleanest path.
  //
  //   Byte packing per VR lane k:
  //     VX[4s+0][k] = table[s×K×4 + k×4 + 0]   (lane k, byte 0)
  //     VX[4s+1][k] = table[s×K×4 + k×4 + 1]   (lane k, byte 1)
  //     VX[4s+2][k] = table[s×K×4 + k×4 + 2]   (lane k, byte 2)
  //     VX[4s+3][k] = table[s×K×4 + k×4 + 3]   (lane k, byte 3)
  //   VR[s][k] = Cat(VX[4s+3][k], VX[4s+2][k], VX[4s+1][k], VX[4s+0][k])
  //            = table[s×K×4 + k×4 + 3..0]   ← little-endian, matches vsetlut protocol
  // ---------------------------------------------------------------------------
  def loadLutBank(dut: NCoreBackend, table: Seq[Int], bank: Int): Unit = {
    val segs = 256 / (K * 4)  // = 8 at K=8
    for (seg <- 0 until segs) {
      // Write 4 VX sub-rows: VX[4*seg+b][k] = table[seg*K*4 + k*4 + b]
      for (b <- 0 until 4) {
        val vrBase = 4 * seg     // VR[seg] starts at VX[4*seg]
        val vxRow  = vrBase + b  // VX row for byte sub-index b
        val rowData = (0 until K).map { k =>
          table(seg * K * 4 + k * 4 + b) & 0xFF
        }.toArray
        extWrite(dut, addr = vxRow, data = rowData)
      }
      // Issue vsetlut: vr_a_addr = seg so in_a_vr reads VR[seg]
      //   vsetlut(rs1=seg, segment=seg, bank=bank)
      //   encodes as I-type: rd=0, rs1=seg, funct3=4+bank, imm=seg
      dut.io.vr_a_addr.poke(seg.U)
      dut.io.vx_out_addr.poke(0.U)  // vsetlut does not write VX; harmless
      dut.io.vr_out_addr.poke(0.U)  // vsetlut does not write RF; harmless
      issue(dut, vsetlut(rs1 = seg, segment = seg, bank = bank))
    }
  }

  // ---------------------------------------------------------------------------
  // Scala reference: full GEMM + Softmax pipeline.
  // accInt8:  K INT8 values (all same broadcast value)
  // scaleInt: INT8 attention scale
  // Returns K INT8 softmax weights.
  // ---------------------------------------------------------------------------
  def gemmSoftmaxRef(accInt8: Array[Int], scaleInt: Int): Array[Int] = {
    val scaleFp  = FpRef.s8ToF32(scaleInt.toByte)
    val scoreFp  = accInt8.map(a => FpRef.fmul(FpRef.s8ToF32(a.toByte), scaleFp))
    val scoreRaw = scoreFp.map(b => FpRef.f32ToS8(b).toInt & 0xFF)
    val scoreSgn = scoreRaw.map(b => if (b >= 128) b - 256 else b)
    val maxSgn   = scoreSgn.max
    val shifted  = scoreSgn.map(x => math.max(-128, math.min(127, x - maxSgn)))
    val shiftRaw = shifted.map(_ & 0xFF)
    val expRaw   = shiftRaw.map(b => Qfmt.lutExp(b) & 0xFF)
    val expSgn   = expRaw.map(b => if (b >= 128) b - 256 else b)
    val sumSgn   = expSgn.map(_.toLong).sum
    val sumClamp = math.max(1, math.min(127, sumSgn.toInt))
    val recipRaw = Qfmt.lutRecip(sumClamp & 0xFF) & 0xFF
    val expFp    = expSgn.map(e => FpRef.s8ToF32(e.toByte))
    val recipSgn = if (recipRaw >= 128) recipRaw - 256 else recipRaw
    val recipFp  = FpRef.s8ToF32(recipSgn.toByte)
    val prodFp   = expFp.map(e => FpRef.fmul(e, recipFp))
    val prodInt  = prodFp.map(b => FpRef.f32ToS32(b))
    val shiftd7  = prodInt.map(p => p >> 7)
    shiftd7.map(v => math.max(-128, math.min(127, v)))
  }

  // ---------------------------------------------------------------------------
  // Core helper: load LUT banks, then run the full pipeline.
  //
  // Register map:
  //   VX[ 0..3]  = LUT sub-rows for segment 0  (also written by extWrite in preamble)
  //   VX[ 4..7]  = LUT sub-rows for segment 1
  //   ...
  //   VX[28..31] = LUT sub-rows for segment 7
  //   (all 32 VX regs used for LUT loading; they are reused freely after vsetlut)
  //
  //   VX[ 0] = scores_sq16    VX[ 1] = shifted_sq16   VX[ 2] = exp_uq08
  //   VX[ 5] = max_byte        VX[ 6] = sum_clamped    VX[ 7] = recip_sq16
  //   VX[ 8] = staging (vbcastImm target)
  //   VR[ 0] = acc_fp32   → product_int32  (reused)
  //   VR[ 1] = scaled_fp32 → shift_amount=7 (reused)
  //   VR[ 2] = scale_fp32  → result (vcvt_s32_s8 output, reused)
  //   VR[ 3] = max_int32   → vsra output (reused)
  //   VR[ 4] = sum_int32
  //   VR[ 5] = exp_fp32    VR[ 6] = recip_fp32   VR[ 7] = product_fp32
  // ---------------------------------------------------------------------------
  def runGemmSoftmax(
      dut:     NCoreBackend,
      accInt8: Array[Int],
      scaleInt: Int
  ): Array[Int] = {

    val accVal = accInt8(0)

    // ----------------------------------------------------------------
    // Preamble: load exp into LUT bank A, recip into LUT bank B.
    // Must be done before the computation kernel.
    // ----------------------------------------------------------------
    loadLutBank(dut, Qfmt.lutExp,   bank = 0)  // bank A
    loadLutBank(dut, Qfmt.lutRecip, bank = 1)  // bank B

    // ----------------------------------------------------------------
    // Phase 0: vbcastImm(acc) → VX[8];  vcvt_s8_f32 → VR[0]
    // ----------------------------------------------------------------
    dut.io.vx_out_addr.poke(8.U)
    issue(dut, vbcastImm(rd = 8, imm = accVal))

    dut.io.vx_a_addr.poke(8.U)
    dut.io.vr_out_addr.poke(0.U)
    issue(dut, vcvt_s8_f32(rd = 0, rs1 = 8))

    // ----------------------------------------------------------------
    // Phase 1: scale → VR[2];  vfmul VR[0]*VR[2] → VR[1]
    // ----------------------------------------------------------------
    dut.io.vx_out_addr.poke(8.U)
    issue(dut, vbcastImm(rd = 8, imm = scaleInt))

    dut.io.vx_a_addr.poke(8.U)
    dut.io.vr_out_addr.poke(2.U)
    issue(dut, vcvt_s8_f32(rd = 2, rs1 = 8))

    dut.io.vr_a_addr.poke(0.U)
    dut.io.vr_b_addr.poke(2.U)
    dut.io.vr_out_addr.poke(1.U)
    issue(dut, vfmul(rd = 1, rs1 = 0, rs2 = 2))

    // ----------------------------------------------------------------
    // Phase 2: FP32 → SQ1.6   VR[1] → VX[0]
    // ----------------------------------------------------------------
    dut.io.vr_a_addr.poke(1.U)
    dut.io.vx_out_addr.poke(0.U)
    issue(dut, vcvt(rd = 0, rs1 = 1, dstFmt = F32, srcFmt = S8, sat = true))

    // ----------------------------------------------------------------
    // Phase 3: vrmax VX[0] → VR[3]; extWrite max → VX[5]; vsub → VX[1]
    // ----------------------------------------------------------------
    dut.io.vx_a_addr.poke(0.U)
    dut.io.vx_out_addr.poke(0.U)
    dut.io.vr_out_addr.poke(3.U)
    issue(dut, vrmax(rd = 3, rs1 = 0))

    val maxByte = peekVR0(dut, 3).toByte.toInt
    extWrite(dut, addr = 5, Array.fill(K)(maxByte))

    dut.io.vx_a_addr.poke(0.U)
    dut.io.vx_b_addr.poke(5.U)
    dut.io.vx_out_addr.poke(1.U)
    issue(dut, vsub(rd = 1, rs1 = 0, rs2 = 5, width = VX, sat = true))

    // ----------------------------------------------------------------
    // Phase 4: vlut bank A (exp)  VX[1] → VX[2]
    // ----------------------------------------------------------------
    dut.io.vx_a_addr.poke(1.U)
    dut.io.vx_out_addr.poke(2.U)
    issue(dut, vlut(rd = 2, rs1 = 1, bank = 0))

    // ----------------------------------------------------------------
    // Phase 5: vsum VX[2] → VR[4]; extWrite clamped sum → VX[6]
    // ----------------------------------------------------------------
    dut.io.vx_a_addr.poke(2.U)
    dut.io.vx_out_addr.poke(2.U)
    dut.io.vr_out_addr.poke(4.U)
    issue(dut, vsum(rd = 4, rs1 = 2))

    val sumInt32   = peekVR0(dut, 4)
    val sumClamped = math.max(1, math.min(127, sumInt32))
    extWrite(dut, addr = 6, Array.fill(K)(sumClamped))

    // ----------------------------------------------------------------
    // Phase 6: vlut bank B (recip)  VX[6] → VX[7]
    // ----------------------------------------------------------------
    dut.io.vx_a_addr.poke(6.U)
    dut.io.vx_out_addr.poke(7.U)
    issue(dut, vlut(rd = 7, rs1 = 6, bank = 1))

    // ----------------------------------------------------------------
    // Phase 7: vcvt_s8_f32(VX[2]→VR[5]);  vcvt_s8_f32(VX[7]→VR[6]);
    //          vfmul VR[5]*VR[6] → VR[7]
    // ----------------------------------------------------------------
    dut.io.vr_out_addr.poke(5.U)
    dut.io.vx_a_addr.poke(2.U)
    dut.io.vx_out_addr.poke(0.U)
    issue(dut, vcvt_s8_f32(rd = 5, rs1 = 2))

    dut.io.vr_out_addr.poke(6.U)
    dut.io.vx_a_addr.poke(7.U)
    issue(dut, vcvt_s8_f32(rd = 6, rs1 = 7))

    dut.io.vr_a_addr.poke(5.U)
    dut.io.vr_b_addr.poke(6.U)
    dut.io.vr_out_addr.poke(7.U)
    issue(dut, vfmul(rd = 7, rs1 = 5, rs2 = 6))

    // ----------------------------------------------------------------
    // Phase 8: vcvt_f32_s32 VR[7]→VR[0]; vsra(>>7) VR[0]→VR[3]
    // ----------------------------------------------------------------
    dut.io.vr_a_addr.poke(7.U)
    dut.io.vr_out_addr.poke(0.U)
    issue(dut, vcvt_f32_s32(rd = 0, rs1 = 7))

    dut.io.vx_out_addr.poke(8.U)
    issue(dut, vbcastImm(rd = 8, imm = 7))

    dut.io.vx_a_addr.poke(8.U)
    dut.io.vr_out_addr.poke(1.U)
    issue(dut, vcvt_s8_f32(rd = 1, rs1 = 8))

    dut.io.vr_a_addr.poke(1.U)
    dut.io.vr_out_addr.poke(1.U)
    issue(dut, vcvt_f32_s32(rd = 1, rs1 = 1))

    dut.io.vr_a_addr.poke(0.U)
    dut.io.vr_b_addr.poke(1.U)
    dut.io.vr_out_addr.poke(3.U)
    issue(dut, vsra(rd = 3, rs1 = 0, rs2 = 1, width = VR))

    // ----------------------------------------------------------------
    // Phase 9: vcvt_s32_s8 sat  VR[3] → VR[2]
    // ----------------------------------------------------------------
    dut.io.vr_a_addr.poke(3.U)
    dut.io.vr_out_addr.poke(2.U)
    issue(dut, vcvt_s32_s8(rd = 2, rs1 = 3))

    dut.io.vr_a_addr.poke(2.U)
    dut.clock.step(0)
    (0 until K).map { i =>
      val raw32 = dut.io.vr_rd_data(i).peek().litValue.toInt
      val low8  = raw32 & 0xFF
      if (low8 >= 128) low8 - 256 else low8
    }.toArray
  }

  // ---- Sub-case helpers ------------------------------------------------------
  //
  // Each sub-case is independent: runGemmSoftmax() reloads both LUT banks at
  // the start (loadLutBank in Phase 0), so register-file state from prior
  // sub-cases is overwritten in the registers it cares about.

  private def runUniform(dut: NCoreBackend): Unit = {
    val accInt8  = Array.fill(K)(10)
    val result   = runGemmSoftmax(dut, accInt8, scaleInt = 1)
    val expected = gemmSoftmaxRef(accInt8, scaleInt = 1)

    for (i <- 0 until K)
      assert(result(i) == expected(i),
        s"[uniform] lane $i: got ${result(i)}, expected ${expected(i)}")

    val lane0 = result(0)
    for (i <- 1 until K)
      assert(result(i) == lane0,
        s"[uniform] uniformity: lane $i=${result(i)} != lane 0=$lane0")
  }

  private def run2xScale(dut: NCoreBackend): Unit = {
    val accInt8  = Array.fill(K)(20)
    val result   = runGemmSoftmax(dut, accInt8, scaleInt = 2)
    val expected = gemmSoftmaxRef(accInt8, scaleInt = 2)

    for (i <- 0 until K)
      assert(result(i) == expected(i),
        s"[2x scale] lane $i: got ${result(i)}, expected ${expected(i)}")

    val lane0 = result(0)
    for (i <- 1 until K)
      assert(result(i) == lane0,
        s"[2x scale] uniformity: lane $i=${result(i)} != lane 0=$lane0")
  }

  private def runNegative(dut: NCoreBackend): Unit = {
    val accInt8  = Array.fill(K)(-20)
    val result   = runGemmSoftmax(dut, accInt8, scaleInt = 1)
    val expected = gemmSoftmaxRef(accInt8, scaleInt = 1)

    for (i <- 0 until K)
      assert(result(i) == expected(i),
        s"[negative] lane $i: got ${result(i)}, expected ${expected(i)}")
  }

  private def run3xScale(dut: NCoreBackend): Unit = {
    val accInt8  = Array.fill(K)(5)
    val result   = runGemmSoftmax(dut, accInt8, scaleInt = 3)
    val expected = gemmSoftmaxRef(accInt8, scaleInt = 3)

    for (i <- 0 until K)
      assert(result(i) == expected(i),
        s"[3x scale] lane $i: got ${result(i)}, expected ${expected(i)}")
  }

  // ---- Coalesced test --------------------------------------------------------

  "NCoreBackendGemmSoftmax" should "pass all GEMM+softmax quantization sub-cases" in {
    withBackend { dut =>
      withClue("uniform scores: ")           { runUniform(dut)  }
      withClue("2x scale: ")                 { run2xScale(dut)  }
      withClue("negative accumulator: ")     { runNegative(dut) }
      withClue("scale=3: ")                  { run3xScale(dut)  }
    }
  }
}

// See README.md for license details.
// -----------------------------------------------------------------------------
//  NpuAssembler.scala — Scala-side assembler for NPU instruction words
//
//  Produces 32-bit UInt literals that can be poked directly into
//  NeuralCoreMicroOp.word in simulation.
//
//  Usage example (in a spec):
//    import isa.NpuAssembler._
//    val instr = vadd(rd=0, rs1=1, rs2=2, width=VX)
//    dut.io.micro_op.word.poke(instr)
//
//  All methods return a Scala Int (bit pattern) that can be converted to
//  UInt via .U in a Chisel context, or wrapped by the asUInt helper.
// -----------------------------------------------------------------------------

package isa

import chisel3._

object NpuAssembler {

  // ---- Constants -----------------------------------------------------------

  // Width selectors (funct7[1:0])
  val VX = 0  // N(bits)-wide lanes
  val VE = 1  // 2N-wide lanes
  val VR = 2  // 4N-wide lanes

  // Rounding modes (funct7[3:2])
  val RNE   = 0
  val RTZ   = 1
  val FLOOR = 2
  val CEIL  = 3

  // Dtype class (funct7[6:5])
  val INT = 0
  val FP  = 1
  val BF  = 2

  // Format codes for vcvt (funct3 = dst, funct7[2:0] = src)
  val S8   = 0
  val S16  = 1
  val S32  = 2
  val F32  = 3
  val BF16 = 4
  val BF8  = 5   // BF8 variant (E4M3 vs E5M2) from bf8E5M2 parameter

  // ---- Encoding helpers ----------------------------------------------------

  /** Encode funct7 for R-type vector ops. */
  def f7(width: Int = VX, round: Int = RNE, sat: Boolean = false, dtype: Int = INT): Int =
    (width & 3) | ((round & 3) << 2) | ((if (sat) 1 else 0) << 4) | ((dtype & 3) << 5)

  /** Encode funct7 for VALU_CVT. */
  def f7Cvt(srcFmt: Int, sat: Boolean = true, round: Int = RNE, bf8E5M2: Boolean = false): Int =
    (srcFmt & 7) | ((if (sat) 1 else 0) << 3) | ((round & 3) << 4) | ((if (bf8E5M2) 1 else 0) << 6)

  /** Build R-type instruction word (returns Long to avoid signed-int overflow at bit 31). */
  def encR(opcode: Int, funct3: Int, funct7: Int, rd: Int, rs1: Int, rs2: Int): Int = {
    val w = (opcode.toLong & 0x7F) |
            ((rd.toLong & 0x1F) << 7) |
            ((funct3.toLong & 0x7) << 12) |
            ((rs1.toLong & 0x1F) << 15) |
            ((rs2.toLong & 0x1F) << 20) |
            ((funct7.toLong & 0x7F) << 25)
    (w & 0xFFFFFFFFL).toInt  // keep 32 bits, return as (possibly signed) Int
  }

  /** Build I-type instruction word (imm is sign-extended 12-bit). */
  def encI(opcode: Int, funct3: Int, rd: Int, rs1: Int, imm: Int): Int = {
    val imm12 = imm.toLong & 0xFFF
    val w = (opcode.toLong & 0x7F) |
            ((rd.toLong & 0x1F) << 7) |
            ((funct3.toLong & 0x7) << 12) |
            ((rs1.toLong & 0x1F) << 15) |
            (imm12 << 20)
    (w & 0xFFFFFFFFL).toInt
  }

  /** Build S-type (FMA) instruction word. rs3 at [31:27], rnd at [26:25]. */
  def encS(opcode: Int, funct3: Int, rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int = {
    val w = (opcode.toLong & 0x7F) |
            ((rd.toLong & 0x1F) << 7) |
            ((funct3.toLong & 0x7) << 12) |
            ((rs1.toLong & 0x1F) << 15) |
            ((rs2.toLong & 0x1F) << 20) |
            ((round.toLong & 0x3) << 25) |
            ((rs3.toLong & 0x1F) << 27)
    (w & 0xFFFFFFFFL).toInt
  }

  // ---- NOP / special -------------------------------------------------------

  val nop: Int = 0x00  // opcode=0x00, everything zero

  // ---- VALU_ARITH (opcode=0x10) --------------------------------------------

  def vadd (rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 0, f7(width, sat=sat), rd, rs1, rs2)
  def vsub (rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 1, f7(width, sat=sat), rd, rs1, rs2)
  def vmul (rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 2, f7(width, sat=sat), rd, rs1, rs2)
  def vneg (rd: Int, rs1: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 3, f7(width, sat=sat), rd, rs1, 0)
  def vabs (rd: Int, rs1: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 4, f7(width, sat=sat), rd, rs1, 0)
  def vmax (rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int =
    encR(0x10, 5, f7(width), rd, rs1, rs2)
  def vmin (rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int =
    encR(0x10, 6, f7(width), rd, rs1, rs2)
  def vrsub(rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 7, f7(width, sat=sat), rd, rs1, rs2)

  // ---- VALU_LOGIC (opcode=0x11) --------------------------------------------

  def vsll(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 0, f7(width), rd, rs1, rs2)
  def vsrl(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 1, f7(width), rd, rs1, rs2)
  def vsra(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 2, f7(width), rd, rs1, rs2)
  def vrol(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 3, f7(width), rd, rs1, rs2)
  def vxor(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 4, f7(width), rd, rs1, rs2)
  def vnot(rd: Int, rs1: Int, width: Int = VX): Int            = encR(0x11, 5, f7(width), rd, rs1, 0)
  def vor (rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int  = encR(0x11, 6, f7(width), rd, rs1, rs2)
  def vand(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int  = encR(0x11, 7, f7(width), rd, rs1, rs2)

  // ---- VALU_REDUCE (opcode=0x12) -------------------------------------------

  def vsum (rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 0, f7(width), rd, rs1, 0)
  def vrmax(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 1, f7(width), rd, rs1, 0)
  def vrmin(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 2, f7(width), rd, rs1, 0)
  def vrand(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 3, f7(width), rd, rs1, 0)
  def vror (rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 4, f7(width), rd, rs1, 0)
  def vrxor(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 5, f7(width), rd, rs1, 0)

  // ---- VALU_LUT (opcode=0x13) — programmable two-bank LUT -------------------
  // Bank select: 0=A (default), 1=B.

  /**
   * Per-lane lookup: out[i] = lut_bank[in_a_vx[i]].
   * bank=0 → bank A (funct3=0), bank=1 → bank B (funct3=1).
   */
  def vlut(rd: Int, rs1: Int, bank: Int = 0): Int =
    encR(0x13, bank & 1, f7(VX), rd, rs1, 0)

  /**
   * Write one K×4-byte segment from VR[rs1] into the selected LUT bank.
   * segment: which K×4-entry block (0-based) within the 256-entry table.
   * bank=0 → bank A (funct3=4), bank=1 → bank B (funct3=5).
   * I-type: rd=0 (no register-file destination); imm=segment.
   */
  def vsetlut(rs1: Int, segment: Int, bank: Int = 0): Int =
    encI(0x13, 4 + (bank & 1), 0, rs1, segment)

  // ---- VALU_CVT (opcode=0x14) ----------------------------------------------
  // funct3 = dst fmt code; f7 encodes src + sat + round + bf8 variant

  def vcvt(rd: Int, rs1: Int,
           dstFmt: Int, srcFmt: Int,
           sat: Boolean = true, round: Int = RNE,
           bf8E5M2: Boolean = false): Int =
    encR(0x14, dstFmt, f7Cvt(srcFmt, sat, round, bf8E5M2), rd, rs1, 0)

  // Convenience aliases
  def vcvt_s8_s32 (rd: Int, rs1: Int, sat: Boolean = true,  round: Int = RNE): Int = vcvt(rd, rs1, S8,   S32, sat, round)
  def vcvt_s32_s8 (rd: Int, rs1: Int): Int = vcvt(rd, rs1, S32, S8)
  def vcvt_s32_f32(rd: Int, rs1: Int, round: Int = RNE): Int = vcvt(rd, rs1, S32, F32, round=round)
  def vcvt_f32_s32(rd: Int, rs1: Int): Int = vcvt(rd, rs1, F32, S32, sat=false)
  def vcvt_f32_s8 (rd: Int, rs1: Int): Int = vcvt(rd, rs1, F32, S8,  sat=false)
  def vcvt_s8_f32 (rd: Int, rs1: Int, sat: Boolean = true, round: Int = RNE): Int = vcvt(rd, rs1, S8,   F32, sat, round)
  def vcvt_f32_bf16(rd: Int, rs1: Int): Int = vcvt(rd, rs1, F32, BF16, sat=false)
  def vcvt_bf16_f32(rd: Int, rs1: Int): Int = vcvt(rd, rs1, BF16, F32, sat=false)
  def vcvt_f32_bf8 (rd: Int, rs1: Int, e5m2: Boolean = false): Int = vcvt(rd, rs1, F32, BF8, sat=false, bf8E5M2=e5m2)
  def vcvt_bf8_f32 (rd: Int, rs1: Int, e5m2: Boolean = false): Int = vcvt(rd, rs1, BF8, F32, sat=false, bf8E5M2=e5m2)
  def vcvt_s16_s32 (rd: Int, rs1: Int, sat: Boolean = true): Int   = vcvt(rd, rs1, S16, S32, sat)
  def vcvt_s32_s16 (rd: Int, rs1: Int): Int = vcvt(rd, rs1, S32, S16, sat=false)

  // ---- VALU_BCAST (opcode=0x15) --------------------------------------------

  /** Broadcast lane 0 of rs1 to all K lanes of rd (R-format). */
  def vbcast(rd: Int, rs1: Int, width: Int = VX): Int =
    encR(0x15, 0, f7(width), rd, rs1, 0)

  /** Broadcast sign-extended 12-bit immediate to all K lanes of rd (I-format). */
  def vbcastImm(rd: Int, imm: Int, width: Int = VX): Int =
    encI(0x15, 1, rd, 0, imm)

  // ---- VALU_FP (opcode=0x16) — FP32 on VR ---------------------------------

  def vfadd(rd: Int, rs1: Int, rs2: Int, round: Int = RNE): Int =
    encR(0x16, 0, f7(VR, round=round, dtype=FP), rd, rs1, rs2)
  def vfsub(rd: Int, rs1: Int, rs2: Int, round: Int = RNE): Int =
    encR(0x16, 1, f7(VR, round=round, dtype=FP), rd, rs1, rs2)
  def vfmul(rd: Int, rs1: Int, rs2: Int, round: Int = RNE): Int =
    encR(0x16, 2, f7(VR, round=round, dtype=FP), rd, rs1, rs2)
  def vfneg(rd: Int, rs1: Int): Int =
    encR(0x16, 3, f7(VR, dtype=FP), rd, rs1, 0)
  def vfabs(rd: Int, rs1: Int): Int =
    encR(0x16, 4, f7(VR, dtype=FP), rd, rs1, 0)
  def vfmax(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x16, 5, f7(VR, dtype=FP), rd, rs1, rs2)
  def vfmin(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x16, 6, f7(VR, dtype=FP), rd, rs1, rs2)

  // ---- VALU_FP_FMA (opcode=0x17) — S-format -------------------------------

  def vfma (rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 0, rd, rs1, rs2, rs3, round)
  def vfms (rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 1, rd, rs1, rs2, rs3, round)
  def vnfma(rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 2, rd, rs1, rs2, rs3, round)
  def vnfms(rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 3, rd, rs1, rs2, rs3, round)

  // ---- VALU_MOV (opcode=0x18) ----------------------------------------------

  def vmov (rd: Int, rs1: Int, width: Int = VX): Int =
    encR(0x18, 0, f7(width), rd, rs1, 0)
  def vmovi(rd: Int, imm: Int, width: Int = VX): Int =
    encI(0x18, 1, rd, 0, imm)
  def vmovh(rd: Int, imm: Int): Int =
    encI(0x18, 2, rd, 0, imm)

  // ---- MMA (opcode=0x03) ---------------------------------------------------

  /** mma rd=outVR, rs1=A_VX_base, rs2=B_VX_base; keep in funct7[4] (sat bit). */
  def mma(rd: Int, rs1: Int, rs2: Int, keep: Boolean = true): Int =
    encR(0x03, 0, f7(VR, sat=keep), rd, rs1, rs2)
  def mmaLast(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x03, 1, f7(VR), rd, rs1, rs2)
  def mmaReset(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x03, 2, f7(VR), rd, rs1, rs2)

  // ---- LD / ST (opcodes 0x01 / 0x02) --------------------------------------

  def ldVx(rd: Int, base: Int, offset: Int = 0): Int = encI(0x01, 3, rd, base, offset)
  def ldVe(rd: Int, base: Int, offset: Int = 0): Int = encI(0x01, 4, rd, base, offset)
  def ldVr(rd: Int, base: Int, offset: Int = 0): Int = encI(0x01, 5, rd, base, offset)
  def stVx(rs2: Int, base: Int, offset: Int = 0): Int = encI(0x02, 3, 0, base, offset)
  def stVe(rs2: Int, base: Int, offset: Int = 0): Int = encI(0x02, 4, 0, base, offset)
  def stVr(rs2: Int, base: Int, offset: Int = 0): Int = encI(0x02, 5, 0, base, offset)

  // ---- Convenience: convert Scala Int to Chisel UInt -----------------------
  implicit class IntToUInt(val v: Int) {
    // Convert to UInt treating the int as an unsigned 32-bit bit pattern
    def asUInt: chisel3.UInt = (v.toLong & 0xFFFFFFFFL).U(32.W)
  }
}

// See README.md for license details.
// -----------------------------------------------------------------------------
//  fp.scala — Tier-2 FP32 / BF16 / BF8 arithmetic helpers
//
//  Design scope (Tier 2):
//    - IEEE 754 binary32 subset: RNE rounding (default), RTZ/floor/ceil optional.
//    - No NaN propagation: NaN inputs are treated as zero; outputs never NaN.
//    - No ±Infinity propagation: overflow saturates to max finite normal.
//    - Subnormals flushed to zero on both input and output (FTZ).
//    - All functions are purely combinational (no registers).
//      The VALU adds a 1-cycle output register around these helpers.
//
//  BF8 variants:
//    E4M3 (1/4/3): bias 7,  max exp = 14 → max value ≈ 448
//    E5M2 (1/5/2): bias 15, max exp = 30 → max value ≈ 57344
//
//  Scala reference functions (for tests and LUT generation) live alongside
//  the Chisel hardware in companion objects.
// -----------------------------------------------------------------------------

package alu.vec

import chisel3._
import chisel3.util._

// ---------------------------------------------------------------------------
// IEEE754 — Chisel combinational FP32 building blocks
// All functions operate on raw UInt(32.W) bit patterns.
// ---------------------------------------------------------------------------
object IEEE754 {

  // FP32 field constants
  val SIGN_BIT  = 31
  val EXP_HI    = 30; val EXP_LO = 23
  val MAN_HI    = 22; val MAN_LO = 0
  val EXP_BIAS  = 127
  val EXP_WIDTH = 8
  val MAN_WIDTH = 23

  // Max finite FP32 (0_11111110_11111111111111111111111) = 0x7F7FFFFF
  val MAX_FP32 = "h7F7FFFFF".U(32.W)
  val MIN_FP32 = "hFF7FFFFF".U(32.W)

  /** Extract sign (1 bit) */
  def sign(f: UInt): UInt = f(SIGN_BIT)

  /** Extract biased exponent (8 bits) */
  def exp(f: UInt): UInt = f(EXP_HI, EXP_LO)

  /** Extract mantissa fraction (23 bits, no implicit 1) */
  def man(f: UInt): UInt = f(MAN_HI, MAN_LO)

  /** True if f is zero (flush-to-zero: subnormals also treated as zero) */
  def isZero(f: UInt): Bool = exp(f) === 0.U

  /** True if f is a NaN or Inf (exponent all-ones) — treated as zero in Tier-2 */
  def isSpecial(f: UInt): Bool = exp(f) === "hFF".U(8.W)

  /** Sanitize: replace NaN/Inf/subnormal with ±0 */
  def sanitize(f: UInt): UInt =
    Mux(isSpecial(f) || isZero(f), Cat(sign(f), 0.U(31.W)), f)

  /** Build FP32 from parts (does NOT check for overflow) */
  def pack(s: UInt, e: UInt, m: UInt): UInt = Cat(s, e(7, 0), m(22, 0))

  // ---------------------------------------------------------------------------
  // fadd32: FP32 addition (sanitised inputs; RNE)
  //   a + b with Tier-2 constraints.
  //   Combinational; latency ~ 1 cycle when registered externally.
  // ---------------------------------------------------------------------------
  def fadd32(a: UInt, b: UInt): UInt = {
    val aS = sanitize(a)
    val bS = sanitize(b)

    val aSign = sign(aS);  val bSign = sign(bS)
    val aExp  = exp(aS).pad(10).asSInt;  val bExp  = exp(bS).pad(10).asSInt
    val aMan  = Cat(1.U(1.W), man(aS))  // add implicit 1; 24 bits
    val bMan  = Cat(1.U(1.W), man(bS))  // 24 bits

    // Swap so that |a| >= |b|
    val swap   = (bExp > aExp) || ((bExp === aExp) && (bMan > aMan))
    val hiExp  = Mux(swap, bExp, aExp)
    val loExp  = Mux(swap, aExp, bExp)
    val hiMan  = Mux(swap, bMan, aMan)
    val loMan  = Mux(swap, aMan, bMan)
    val hiSign = Mux(swap, bSign, aSign)
    val loSign = Mux(swap, aSign, bSign)

    // Shift smaller operand right to align
    val shift = (hiExp - loExp).asUInt
    val shiftCap = Mux(shift > 25.U, 25.U, shift)
    val loAligned = (loMan >> shiftCap)(23, 0)  // 24 bits, shifted

    // Add or subtract based on signs
    val sameSign = hiSign === loSign
    // Extend to 25 bits to catch carry/borrow
    val hiExt = Cat(0.U(1.W), hiMan)   // 25 bits
    val loExt = Cat(0.U(1.W), loAligned)

    val raw = WireDefault(0.U(25.W))
    val rSign = WireDefault(hiSign)
    when (sameSign) {
      raw := hiExt + loExt
    } .otherwise {
      when (hiExt >= loExt) {
        raw := hiExt - loExt
      } .otherwise {
        raw  := loExt - hiExt
        rSign := ~hiSign
      }
    }

    // Normalise raw[24:0]:
    //   PriorityEncoder(Reverse(x)) gives the highest-set-bit position from LSB,
    //   which equals 24 - (number of leading zeros from bit 24).
    //   Let hbit = 24 - PriorityEncoder(Reverse(raw)) = position of leading 1.
    //   Normalised mantissa = raw << (23 - hbit), i.e. shift = 23 - hbit.
    //   Exponent adjustment = hbit - 23.
    //   rExp = hiExp + (hbit - 23).
    //
    //   Special case: bit 24 set (carry out from addition):
    //     hbit = 24, shift = -1 (shift right by 1), rExp = hiExp + 1.
    val lzFromTop = PriorityEncoder(Reverse(raw(24, 0)))  // = highest set bit position
    val rExp = WireDefault(0.S(10.W))
    val rMan = WireDefault(0.U(23.W))

    val rawTop = raw(24)
    when (rawTop) {
      // Leading 1 at bit 24 (carry): shift right 1, exp += 1
      rExp := hiExp + 1.S
      rMan := raw(23, 1)
    } .elsewhen (raw =/= 0.U) {
      // Leading 1 at bit lzFromTop; shift left by (23 - lzFromTop)
      // Exponent adjustment: (lzFromTop - 23)
      // hbit = position of highest set bit in raw (0-indexed from LSB)
      // lzFromTop = index in reversed vector = (24 - hbit), so hbit = 24 - lzFromTop
      val hbit = 24.U - lzFromTop
      when (hbit >= 23.U) {
        // Leading 1 at bit >= 23: shift right by (hbit - 23)
        val shiftR = hbit - 23.U
        rExp := hiExp + shiftR.asSInt
        rMan := (raw >> shiftR)(22, 0)
      } .otherwise {
        // Leading 1 at bit < 23: shift left by (23 - hbit)
        val shiftL = 23.U - hbit
        rExp := hiExp - shiftL.asSInt
        rMan := (raw << shiftL)(22, 0)
      }
    }
    // else: result is zero → rExp=0, rMan=0 (defaults)

    // Saturate on overflow / underflow
    val overflow  = rExp >= 255.S
    val underflow = (rExp <= 0.S) || (raw === 0.U)

    val outBits = WireDefault(0.U(32.W))
    when (overflow) {
      outBits := Mux(rSign === 0.U, MAX_FP32, MIN_FP32)
    } .elsewhen (underflow) {
      outBits := Cat(rSign, 0.U(31.W))  // ±0
    } .otherwise {
      outBits := pack(rSign, rExp.asUInt, rMan)
    }
    outBits
  }

  // ---------------------------------------------------------------------------
  // fmul32: FP32 multiplication (sanitised inputs; RNE)
  // ---------------------------------------------------------------------------
  def fmul32(a: UInt, b: UInt): UInt = {
    val aS = sanitize(a)
    val bS = sanitize(b)

    val rSign = sign(aS) ^ sign(bS)
    val aExp  = exp(aS).pad(10).asSInt
    val bExp  = exp(bS).pad(10).asSInt
    val aMan  = Cat(1.U(1.W), man(aS))  // 24 bits
    val bMan  = Cat(1.U(1.W), man(bS))  // 24 bits

    // Product: 48 bits; exponent = aExp + bExp - bias
    val prod    = aMan * bMan              // 48-bit product
    val rExpRaw = aExp + bExp - EXP_BIAS.S

    // Either bit 47 or 46 holds the leading 1
    val prodTop = prod(47)
    val rExp    = WireDefault(0.S(10.W))
    val rMan    = WireDefault(0.U(23.W))

    val isZeroResult = isZero(aS) || isZero(bS)
    when (!isZeroResult) {
      when (prodTop) {
        rExp := rExpRaw + 1.S
        rMan := prod(46, 24)
      } .otherwise {
        rExp := rExpRaw
        rMan := prod(45, 23)
      }
    }

    val overflow  = rExp >= 255.S
    val underflow = (rExp <= 0.S) || isZeroResult

    val outBits = WireDefault(0.U(32.W))
    when (overflow) {
      outBits := Mux(rSign === 0.U, MAX_FP32, MIN_FP32)
    } .elsewhen (underflow) {
      outBits := Cat(rSign, 0.U(31.W))
    } .otherwise {
      outBits := pack(rSign, rExp.asUInt, rMan)
    }
    outBits
  }

  // ---------------------------------------------------------------------------
  // fma32: fused multiply-add: (a * b) + c
  // Tier-2: not truly fused (two operations); matches 1-ULP accuracy for
  // the quantisation use case where intermediate results are finite & normal.
  // ---------------------------------------------------------------------------
  def fma32(a: UInt, b: UInt, c: UInt): UInt = fadd32(fmul32(a, b), c)
  def fms32(a: UInt, b: UInt, c: UInt): UInt = fadd32(fmul32(a, b), fneg32(c))
  def nfma32(a: UInt, b: UInt, c: UInt): UInt = fadd32(fneg32(fmul32(a, b)), c)
  def nfms32(a: UInt, b: UInt, c: UInt): UInt = fneg32(fma32(a, b, c))

  // ---------------------------------------------------------------------------
  // Negate / abs: just flip/clear the sign bit
  // ---------------------------------------------------------------------------
  def fneg32(f: UInt): UInt = Cat(~f(31), f(30, 0))
  def fabs32(f: UInt): UInt = Cat(0.U(1.W), f(30, 0))

  // ---------------------------------------------------------------------------
  // fmax32 / fmin32: lane-wise comparison (NaN treated as zero)
  // ---------------------------------------------------------------------------
  def fmax32(a: UInt, b: UInt): UInt = {
    val aS = sanitize(a); val bS = sanitize(b)
    // Compare as signed magnitude: negative FP32 is larger magnitude but smaller value
    Mux(aS.asSInt > bS.asSInt, aS, bS)
  }
  def fmin32(a: UInt, b: UInt): UInt = {
    val aS = sanitize(a); val bS = sanitize(b)
    Mux(aS.asSInt < bS.asSInt, aS, bS)
  }

  // ---------------------------------------------------------------------------
  // INT ↔ FP32 conversions
  // ---------------------------------------------------------------------------

  /** INT32 → FP32 (exact for values ≤ 2^23; round-to-nearest for larger) */
  def s32ToF32(s: SInt): UInt = {
    val neg   = s < 0.S(32.W)
    val mag   = Mux(neg, (-s).asUInt, s.asUInt)    // magnitude
    val msb   = (31.U - PriorityEncoder(Reverse(mag))).asUInt  // position of leading 1
    val rSign = neg.asUInt
    // Guard: if mag == 0, output is 0
    val isZeroI = mag === 0.U
    // Normalise: shift mag left so leading 1 is at bit 23
    val shift = WireDefault(0.U(5.W))
    when (msb > 23.U) { shift := (msb - 23.U)(4, 0) }
    val rMan = WireDefault(0.U(23.W))
    when (!isZeroI) {
      when (msb >= 23.U) { rMan := (mag >> (msb - 23.U))(22, 0) }
      .otherwise         { rMan := (mag << (23.U - msb))(22, 0) }
    }
    val rExp = Mux(isZeroI, 0.U, (msb.pad(9) + EXP_BIAS.U(9.W))(7, 0))
    Mux(isZeroI, 0.U, pack(rSign, rExp, rMan))
  }

  /** FP32 → INT32, RTZ (truncate toward zero, saturate) */
  def f32ToS32RTZ(f: UInt): SInt = {
    val fS = sanitize(f)
    val fSign = sign(fS)
    val fExp  = exp(fS)
    val fMan  = Cat(1.U(1.W), man(fS))  // 24 bits

    // exponent biased: unbiased = fExp - 127
    val unbiased = fExp.asSInt - EXP_BIAS.S

    val result = WireDefault(0.S(32.W))
    when (!isZero(fS)) {
      when (unbiased >= 31.S) {
        // Overflow: saturate
        result := Mux(fSign === 0.U, 0x7FFFFFFF.S(32.W), 0x80000000L.S(32.W))
      } .elsewhen (unbiased >= 23.S) {
        // Shift left
        val sh = (unbiased - 23.S).asUInt
        val mag = (fMan << sh)(31, 0)
        result := Mux(fSign === 0.U, mag.asSInt, -(mag.asSInt))
      } .elsewhen (unbiased >= 0.S) {
        // Shift right (truncate)
        val sh = (23.S - unbiased).asUInt
        val mag = (fMan >> sh)(23, 0)
        result := Mux(fSign === 0.U, mag.asSInt, -(mag.asSInt))
      }
      // else: |f| < 1 → 0
    }
    result
  }

  /** FP32 → INT32 with round mode selection (0=RTZ, else RTZ for simplicity in Tier-2) */
  def f32ToS32(f: UInt, round: UInt): SInt = f32ToS32RTZ(f)

  /** INT8 → FP32 (exact, always representable) */
  def s8ToF32(s: SInt): UInt = s32ToF32(s.asTypeOf(SInt(32.W)))

  /** FP32 → INT8 saturated, RTZ */
  def f32ToS8(f: UInt, round: UInt): SInt = {
    val s32 = f32ToS32(f, round)
    val sat = Wire(SInt(8.W))
    sat := MuxCase(s32(7, 0).asSInt, Seq(
      (s32 > 127.S(32.W))   -> 127.S(8.W),
      (s32 < (-128).S(32.W)) -> (-128).S(8.W),
    ))
    sat
  }

  // ---------------------------------------------------------------------------
  // BF16 ↔ FP32: top-16-bits aliasing
  // ---------------------------------------------------------------------------

  /** FP32 → BF16: truncate low 16 bits (RNE: round up if bit 15 and any lower bit set) */
  def f32ToBf16(f: UInt): UInt = {
    // Simple RNE: add 0x8000 to round, then truncate
    val rounded = f + "h00008000".U
    rounded(31, 16)
  }

  /** BF16 → FP32: zero-pad low 16 bits */
  def bf16ToF32(b: UInt): UInt = Cat(b(15, 0), 0.U(16.W))

  // ---------------------------------------------------------------------------
  // BF8 ↔ FP32
  //   E4M3 (1b sign, 4b exp bias=7,  3b mantissa; max normal ≈ 448)
  //   E5M2 (1b sign, 5b exp bias=15, 2b mantissa; max normal ≈ 57344)
  // ---------------------------------------------------------------------------

  /** FP32 → BF8 E4M3 */
  def f32ToBf8E4M3(f: UInt): UInt = {
    val fS   = sanitize(f)
    val fSgn = sign(fS)
    val fExp = exp(fS).asSInt - EXP_BIAS.S  // unbiased
    val fMan = man(fS)

    // E4M3 unbiased range: [-6, 7] (biased [1..14]); 0 for zero
    val result = WireDefault(0.U(8.W))
    when (!isZero(fS)) {
      val eRaw = fExp + 7.S  // re-bias to 7
      when (eRaw >= 15.S) {
        // Overflow: max normal
        result := Cat(fSgn, "b01111111".U(7.W))
      } .elsewhen (eRaw > 0.S) {
        result := Cat(fSgn, eRaw(3, 0), fMan(22, 20))
      }
      // else underflow / subnormal → 0
    }
    result
  }

  /** BF8 E4M3 → FP32 */
  def bf8E4M3ToF32(b: UInt): UInt = {
    val sgn  = b(7)
    val bExp = b(6, 3)
    val bMan = b(2, 0)
    val isZ  = (bExp === 0.U) && (bMan === 0.U)
    val fExp = (bExp.asSInt - 7.S + EXP_BIAS.S).asUInt(7, 0)
    val fMan = Cat(bMan, 0.U(20.W))
    Mux(isZ, Cat(sgn, 0.U(31.W)), pack(sgn, fExp, fMan))
  }

  /** FP32 → BF8 E5M2 */
  def f32ToBf8E5M2(f: UInt): UInt = {
    val fS   = sanitize(f)
    val fSgn = sign(fS)
    val fExp = exp(fS).asSInt - EXP_BIAS.S
    val fMan = man(fS)

    val result = WireDefault(0.U(8.W))
    when (!isZero(fS)) {
      val eRaw = fExp + 15.S
      when (eRaw >= 31.S) {
        result := Cat(fSgn, "b0111111".U(7.W))
      } .elsewhen (eRaw > 0.S) {
        result := Cat(fSgn, eRaw(4, 0), fMan(22, 21))
      }
    }
    result
  }

  /** BF8 E5M2 → FP32 */
  def bf8E5M2ToF32(b: UInt): UInt = {
    val sgn  = b(7)
    val bExp = b(6, 2)
    val bMan = b(1, 0)
    val isZ  = (bExp === 0.U) && (bMan === 0.U)
    val fExp = (bExp.asSInt - 15.S + EXP_BIAS.S).asUInt(7, 0)
    val fMan = Cat(bMan, 0.U(21.W))
    Mux(isZ, Cat(sgn, 0.U(31.W)), pack(sgn, fExp, fMan))
  }

  // Dispatch based on a Bool (false=E4M3, true=E5M2)
  def f32ToBf8(f: UInt, e5m2: Bool): UInt =
    Mux(e5m2, f32ToBf8E5M2(f), f32ToBf8E4M3(f))
  def bf8ToF32(b: UInt, e5m2: Bool): UInt =
    Mux(e5m2, bf8E5M2ToF32(b), bf8E4M3ToF32(b))

  // ---------------------------------------------------------------------------
  // INT16 ↔ INT32 (sign-extend / saturate-narrow)
  // ---------------------------------------------------------------------------
  def s16ToS32(s: SInt): SInt = s.asTypeOf(SInt(32.W))
  def s32ToS16(s: SInt): SInt = {
    val sat = Wire(SInt(16.W))
    sat := MuxCase(s(15, 0).asSInt, Seq(
      (s > 32767.S(32.W))   -> 32767.S(16.W),
      (s < (-32768).S(32.W)) -> (-32768).S(16.W),
    ))
    sat
  }
}

// ---------------------------------------------------------------------------
// Scala-reference functions for test specs (not synthesised)
// ---------------------------------------------------------------------------
object FpRef {
  import java.lang.{Float => JFloat, Integer => JInt}

  def f32Bits(f: Float): Int = JFloat.floatToRawIntBits(f)
  def bitsF32(i: Int): Float = JFloat.intBitsToFloat(i)

  def fadd(aBits: Int, bBits: Int): Int =
    f32Bits(bitsF32(aBits) + bitsF32(bBits))
  def fmul(aBits: Int, bBits: Int): Int =
    f32Bits(bitsF32(aBits) * bitsF32(bBits))
  def fma(aBits: Int, bBits: Int, cBits: Int): Int =
    f32Bits(Math.fma(bitsF32(aBits).toDouble, bitsF32(bBits).toDouble, bitsF32(cBits).toDouble).toFloat)

  def s32ToF32(s: Int): Int = f32Bits(s.toFloat)
  def f32ToS32(bits: Int): Int = bitsF32(bits).toInt   // RTZ per Java cast
  def s8ToF32(s: Byte): Int  = f32Bits(s.toFloat)
  def f32ToS8(bits: Int): Byte = {
    val f = bitsF32(bits)
    if (f >= 127.0f) 127 else if (f <= -128.0f) -128 else f.toInt.toByte
  }

  /** BF16 encode: top 16 bits of FP32 (round-nearest) */
  def f32ToBf16Bits(bits: Int): Int = ((bits + 0x8000) >> 16) & 0xFFFF
  def bf16BitsToF32(bf: Int): Int  = (bf & 0xFFFF) << 16

  /** BF8 E4M3 reference encoder */
  def f32ToBf8E4M3(bits: Int): Int = {
    val f = bitsF32(bits)
    if (f.isNaN || f == 0.0f) 0
    else {
      val sgn = if (bits < 0) 0x80 else 0
      val absF = Math.abs(f.toDouble)
      val exp  = Math.getExponent(f).max(-6).min(7)
      val scale = Math.pow(2.0, exp)
      val man3  = Math.round((absF / scale - 1.0) * 8.0).toInt.min(7).max(0)
      val eBiased = (exp + 7).max(0).min(15)
      sgn | ((eBiased & 0xF) << 3) | (man3 & 0x7)
    }
  }

  /** BF8 E5M2 reference encoder */
  def f32ToBf8E5M2(bits: Int): Int = {
    val f = bitsF32(bits)
    if (f.isNaN || f == 0.0f) 0
    else {
      val sgn = if (bits < 0) 0x80 else 0
      val absF = Math.abs(f.toDouble)
      val exp  = Math.getExponent(f).max(-14).min(15)
      val scale = Math.pow(2.0, exp)
      val man2  = Math.round((absF / scale - 1.0) * 4.0).toInt.min(3).max(0)
      val eBiased = (exp + 15).max(0).min(31)
      sgn | ((eBiased & 0x1F) << 2) | (man2 & 0x3)
    }
  }
}

