   * funct7[1:0] (e.g. vsum.vx uses regCls=VX to select the VX reduction path),
   * but the output is always VR-width.  The backend's regCls===VR guard therefore
   * misses these ops when issued on VX or VE inputs.
   */
  def isReduceToVR(op: VecOp.Type): Bool = {
    op === VecOp.vsum  ||
    op === VecOp.vrmax ||
    op === VecOp.vrmin
  }
}

import chisel3._
import chisel3.util._
import isa.micro_op._

// ---------------------------------------------------------------------------
// Q-format reference tables (shared with test specs for bit-exact checks)
// ---------------------------------------------------------------------------
object Qfmt {
  val FRAC_BITS = 6
  val IN_SCALE  = 1 << FRAC_BITS  // 64
  val EXP_SCALE = 256              // UQ0.8 for vexp output
  val OUT_SCALE = IN_SCALE

  def sq16ToDouble(raw: Int): Double = {
    val signed = if (raw >= 128) raw - 256 else raw
    signed.toDouble / IN_SCALE
  }

  def doubleToSq16(v: Double): Int = {
    val scaled = math.round(v * IN_SCALE).toInt
    math.max(-128, math.min(127, scaled))
  }

  def doubleToUq08(v: Double): Int = {
    val scaled = math.round(v * EXP_SCALE).toInt
    math.max(0, math.min(255, scaled))
  }

  // vexp: SQ1.6 → UQ0.8 stored as SInt(8.W) two's-complement
  val lutExp: Seq[Int] = Seq.tabulate(256) { raw =>
    val x = sq16ToDouble(raw)
    val e = math.exp(x)
    val u = doubleToUq08(math.min(e, 255.0 / EXP_SCALE))
    if (u > 127) u - 256 else u
  }

  val lutRecip: Seq[Int] = Seq.tabulate(256) { raw =>
    val x = sq16ToDouble(raw)
    if (x == 0.0) 127 else doubleToSq16(1.0 / x)
  }

  val lutTanh: Seq[Int] = Seq.tabulate(256) { raw =>
    doubleToSq16(math.tanh(sq16ToDouble(raw)))
  }

  val lutErf: Seq[Int] = Seq.tabulate(256) { raw =>
    doubleToSq16(erfApprox(sq16ToDouble(raw)))
  }

  private def erfApprox(x: Double): Double = {
    val sign = if (x < 0) -1.0 else 1.0
    val t = 1.0 / (1.0 + 0.3275911 * math.abs(x))
    val poly = t * (0.254829592 +
      t * (-0.284496736 +
      t * (1.421413741 +
      t * (-1.453152027 +
      t * 1.061405429))))
    sign * (1.0 - poly * math.exp(-x * x))
  }
}

// ---------------------------------------------------------------------------
// VALU — K-lane vector ALU, multi-width
// ---------------------------------------------------------------------------
class VALU(val K: Int = 8, val N: Int = 8) extends Module {

  val N2 = 2 * N
  val N4 = 4 * N

  val io = IO(new Bundle {
    // Three-width input ports; backend muxes the correct one for each op
    val in_a_vx = Input(Vec(K, UInt(N.W)))
    val in_a_ve = Input(Vec(K, UInt(N2.W)))
    val in_a_vr = Input(Vec(K, UInt(N4.W)))
    val in_b_vx = Input(Vec(K, UInt(N.W)))
    val in_b_ve = Input(Vec(K, UInt(N2.W)))
    val in_b_vr = Input(Vec(K, UInt(N4.W)))
    val in_c_vr = Input(Vec(K, UInt(N4.W)))  // FMA third operand

    val ctrl = Input(new NCoreVALUBundle)

    // Three-width registered outputs (1-cycle latency)
    val out_vx = Output(Vec(K, UInt(N.W)))
    val out_ve = Output(Vec(K, UInt(N2.W)))
    val out_vr = Output(Vec(K, UInt(N4.W)))
  })

  // ---- Programmable LUT banks (256 entries × N bits each) ----
  // Two independent banks (A and B) allow double-buffering: one bank serves an
  // active vlut while the other is preloaded with the next table via vsetlut.
  //
  // Banks are written by vsetlut (one K×4-byte segment per call) and read by vlut.
  // The Qfmt reference tables (exp, recip, tanh, erf) are compiler/test utilities;
  // they are no longer synthesised as hardware ROMs.
  val lutBankA = RegInit(VecInit(Seq.fill(256)(0.U(N.W))))
  val lutBankB = RegInit(VecInit(Seq.fill(256)(0.U(N.W))))

  // ---- Saturation helpers ----
  def satN(v: SInt, w: Int): SInt = {
    val maxV =  ((1 << (w-1)) - 1).S(w.W)
    val minV = (-(1 << (w-1))).S(w.W)
    Mux(v > maxV, maxV, Mux(v < minV, minV, v))
  }

  def satOrTrunc(v: SInt, doSat: Bool, outW: Int): SInt =
    Mux(doSat, satN(v, outW), v(outW-1, 0).asSInt)

  // ---- Wire up raw output buses ----
  val rawVX = Wire(Vec(K, UInt(N.W)))
  val rawVE = Wire(Vec(K, UInt(N2.W)))

// mmalu.io.out is Vec(K, SInt(N4.W)) = Vec(K, SInt(32.W)) for N=8
when (dec.family === OpFamily.MMA) {
  rf.io.vr_w_en(1)   := true.B
  rf.io.vr_w_addr(1) := io.mma_out_addr
  for (lane <- 0 until K) {
    rf.io.vr_w_data(1)(lane) := mmalu.io.out(lane).asUInt
  }
}

// ==========================================================================
// VALU
// ==========================================================================
val valu = Module(new VALU(K, N))

// Connect inputs from RF
for (lane <- 0 until K) {
  valu.io.in_a_vx(lane) := rf.io.vx_r_data(1)(lane)
  valu.io.in_b_vx(lane) := rf.io.vx_r_data(2)(lane)
  valu.io.in_a_ve(lane) := rf.io.ve_r_data(0)(lane)
  valu.io.in_b_ve(lane) := rf.io.ve_r_data(1)(lane)
  valu.io.in_a_vr(lane) := rf.io.vr_r_data(0)(lane)
  valu.io.in_b_vr(lane) := rf.io.vr_r_data(1)(lane)
  valu.io.in_c_vr(lane) := rf.io.vr_r_data(1)(lane)  // C re-uses B port for now
}

// Drive VALU ctrl from decoded bundle
valu.io.ctrl := dec.valu

// Determine if this is a VALU family
val isVALU = dec.family === OpFamily.VALU_ARITH  ||
             dec.family === OpFamily.VALU_LOGIC   ||
             dec.family === OpFamily.VALU_REDUCE  ||
             dec.family === OpFamily.VALU_LUT     ||
             dec.family === OpFamily.VALU_CVT     ||
             dec.family === OpFamily.VALU_BCAST   ||
             dec.family === OpFamily.VALU_FP      ||
             dec.family === OpFamily.VALU_FP_FMA  ||
             dec.family === OpFamily.VALU_MOV

// VALU write-back (port 0 for each class)
when (isVALU) {
  // VX write-back.
  // isReduceToVR ops (vsum, vrmax, vrmin) encode their *input* class in regCls
  // (e.g. vsum.vx has regCls=VX so the VALU selects the VX reduction path).
  // That would accidentally assert vx_w_en and clobber vx_out_addr — suppress it.
  // isSetLut ops (vsetlut) write only to VALU-internal bank registers;
  // all RF write ports must be suppressed.
  rf.io.vx_w_en(0)   := ((dec.valu.regCls === W.VX) || isNarrowCvtOut(dec.valu.op)) &&
                         !isReduceToVR(dec.valu.op) &&
                         !isSetLut(dec.valu.op)
  rf.io.vx_w_addr(0) := io.vx_out_addr
  for (lane <- 0 until K) rf.io.vx_w_data(0)(lane) := valu.io.out_vx(lane)

  // VE write-back
  rf.io.ve_w_en(0)   := dec.valu.regCls === W.VE
  rf.io.ve_w_addr(0) := io.ve_out_addr
  for (lane <- 0 until K) rf.io.ve_w_data(0)(lane) := valu.io.out_ve(lane)

  // VR write-back (FP/INT32, wide conversion results, and horizontal reductions).
  // vsetlut has regCls=VR but must NOT write the RF — suppress it.
